<script setup>
import{ref,computed}from'vue';import{Plus,Search}from'lucide-vue-next';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import{state,persist}from'../data/store';const q=ref(''),show=ref(false),error=ref(''),form=ref({product:'',type:'ENTRADA',qty:1,note:''});const filtered=computed(()=>[...state.movements].sort((a,b)=>new Date(b.date)-new Date(a.date)).filter(m=>Object.values(m).join(' ').toLowerCase().includes(q.value.toLowerCase())));function open(){form.value={product:state.products[0]?.name||'',type:'ENTRADA',qty:1,note:''};error.value='';show.value=true}function save(){error.value='';const qty=Number(form.value.qty);if(qty<=0){error.value='A quantidade deve ser maior que zero.';return}const p=state.products.find(x=>x.name===form.value.product);if(!p)return;if(form.value.type==='SAÍDA'&&p.qty<qty){error.value=`Estoque insuficiente. Disponível: ${p.qty}.`;return}p.qty+=form.value.type==='ENTRADA'?qty:-qty;state.movements.push({id:Date.now(),product:p.name,type:form.value.type,qty,date:new Date().toISOString(),user:state.user.name,note:form.value.note});persist();show.value=false}const fmt=d=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(d))
</script><template><PageHeader title="Movimentações" subtitle="Registre e acompanhe entradas e saídas do estoque."><button class="btn btn-primary" @click="open"><Plus :size="18"/>Nova movimentação</button></PageHeader><section class="panel"><div class="toolbar"><div class="search"><Search :size="18"/><input v-model="q" placeholder="Buscar movimentação..."/></div></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Tipo</th><th>Quantidade</th><th>Responsável</th><th>Data</th><th>Observação</th></tr></thead><tbody><tr v-for="m in filtered" :key="m.id"><td><b>{{m.product}}</b></td><td><span class="badge" :class="m.type==='ENTRADA'?'badge-success':'badge-danger'">{{m.type}}</span></td><td>{{m.qty}}</td><td>{{m.user}}</td><td>{{fmt(m.date)}}</td><td>{{m.note||'—'}}</td></tr></tbody></table></div></section><Modal v-if="show" title="Registrar movimentação" @close="show=false"><form class="form-grid" @submit.prevent="save"><div class="field full"><label>Produto</label><select v-model="form.product"><option v-for="p in state.products" :key="p.id">{{p.name}}</option></select></div><div class="field"><label>Tipo</label><select v-model="form.type"><option>ENTRADA</option><option>SAÍDA</option></select></div><div class="field"><label>Quantidade</label><input v-model="form.qty" type="number" min="1" required/></div><div class="field full"><label>Observação</label><textarea v-model="form.note" rows="3"></textarea></div><p v-if="error" class="form-error full">{{error}}</p><div class="modal-actions full"><button type="button" class="btn btn-secondary" @click="show=false">Cancelar</button><button class="btn btn-primary">Registrar</button></div></form></Modal></template>
